{"command": "python3 - <<'EOF'
import json, glob, os, collections
totals=collections.defaultdict(int)
malformed=[]
for p in sorted(glob.glob('orders/*.json')):
    try:
        with open(p, encoding='utf-8') as f:
            d=json.load(f)
    except (json.JSONDecodeError, UnicodeDecodeError):
        malformed.append(os.path.basename(p))
        continue
    if d['category']=='refund':
        continue
    totals[d['category']]+=d['amount_cents']
summary={'totals':dict(sorted(totals.items())),'malformed':sorted(malformed)}
with open('summary.json','w',encoding='utf-8') as f:
    json.dump(summary,f,indent=2)
    f.write('\n')
print(json.dumps(summary,indent=2))
EOF", "description": "Compute totals and write summary.json"}

